export type Language = "en" | "fr" | "it" | "es" | "ar" | "pt";

export const LANGUAGES: { code: Language; label: string; flag: string }[] = [
  { code: "en", label: "English", flag: "🇬🇧" },
  { code: "fr", label: "Français", flag: "🇫🇷" },
  { code: "it", label: "Italiano", flag: "🇮🇹" },
  { code: "es", label: "Español", flag: "🇪🇸" },
  { code: "ar", label: "العربية", flag: "🇸🇦" },
  { code: "pt", label: "Português", flag: "🇵🇹" },
];

export type QuizQuestion =
  | { type: "single"; q: string; options: string[]; answer: number }
  | { type: "multi"; q: string; options: string[] }
  | { type: "scale"; q: string; min: number; max: number; low: string; high: string }
  | { type: "text"; q: string; placeholder: string };

export type Book = {
  id: string;
  title: string;
  author: string;
  minutes: number;
  hue: number; // for typographic cover
  tagline: string;      // one sentence that captures the whole book
  insight: string;      // opening line for reader
  keyInsights: string[]; // 5 rich "wise friend" interpretations (2-3 paragraphs each)
  actionSteps: string[]; // 3 practical this-week actions
  quote: string;
  quiz: QuizQuestion[];  // 5 questions, mixed types
};

export function amazonSearchUrl(b: Book): string {
  return `https://www.amazon.com/s?k=${encodeURIComponent(`${b.title} ${b.author}`)}&tag=yesalsakhel-20`;
}

