// ---- Deepstash-style comprehension quiz, built from the book's own content ----
export type ComprehensionQuestion = { q: string; options: string[]; answer: number; why: string };

function headline(insight: string): string {
  const m = insight.match(/\*\*([^*]+)\*\*/);
  return (m ? m[1] : insight.slice(0, 60)).replace(/[.:]$/, "");
}

function pickOthers<T>(pool: T[], exclude: (t: T) => boolean, n: number, seed: number): T[] {
  const items = pool.filter((p) => !exclude(p));
  const out: T[] = [];
  for (let i = 0; i < n && items.length; i++) {
    out.push(items[(seed * (i + 3) * 7 + i * 13) % items.length]);
  }
  return out;
}

function shuffleWithAnswer(correct: string, wrong: string[], seed: number) {
  const all = [correct, ...wrong];
  const at = seed % all.length;
  const rest = all.slice(1);
  const options = [...rest.slice(0, at), correct, ...rest.slice(at)];
  return { options, answer: at };
}

export type QuizPack = {
  authored: { q: string; options: string[]; answer: number }[];
  ideaWrong: string[];
  stepWrong: string[];
  quoteWrong: string[];
};

/** The raw, translatable pieces a comprehension quiz is built from. */
export function quizPack(book: Book): QuizPack {
  const seed = book.title.length + book.hue;
  return {
    authored: book.quiz
      .filter((q): q is Extract<QuizQuestion, { type: "single" }> => q.type === "single")
      .map((q) => ({ q: q.q, options: q.options, answer: q.answer })),
    ideaWrong: pickOthers(BOOKS, (b) => b.id === book.id, 3, seed).map((b) => headline(b.keyInsights[0])),
    stepWrong: pickOthers(BOOKS, (b) => b.id === book.id, 3, seed + 5).map((b) => b.actionSteps[0]),
    quoteWrong: pickOthers(BOOKS, (b) => b.id === book.id, 3, seed + 9).map((b) => b.quote),
  };
}

export type QuizLabels = {
  ideaQ: string;
  ideaWhy: string;
  stepQ: string;
  stepWhy: string;
  quoteQ: string;
  quoteWhy: string;
  authoredWhy: string;
};

const EN_LABELS = (book: Book): QuizLabels => ({
  ideaQ: `Which of these is a core idea from ${book.title}?`,
  ideaWhy: "This is one of the five key insights in this summary.",
  stepQ: "Which action step does this summary ask you to take?",
  stepWhy: "This is the first of the three action steps above.",
  quoteQ: `Which line is the quote to remember from ${book.title}?`,
  quoteWhy: `This is the "Remember this" quote from ${book.author}.`,
  authoredWhy: `${book.author} makes this the backbone of ${book.title}.`,
});

export function comprehensionQuiz(book: Book, pack?: QuizPack, labels?: QuizLabels): ComprehensionQuestion[] {
  const seed = book.title.length + book.hue;
  const p = pack ?? quizPack(book);
  const l = labels ?? EN_LABELS(book);

  const qs: ComprehensionQuestion[] = p.authored.map((q) => ({
    q: q.q,
    options: q.options,
    answer: q.answer,
    why: l.authoredWhy,
  }));

  const idea = headline(book.keyInsights[2] ?? book.keyInsights[0]);
  const ideaSet = shuffleWithAnswer(idea, p.ideaWrong, seed);
  qs.push({ q: l.ideaQ, ...ideaSet, why: l.ideaWhy });

  const stepSet = shuffleWithAnswer(book.actionSteps[0], p.stepWrong, seed + 1);
  qs.push({ q: l.stepQ, ...stepSet, why: l.stepWhy });

  const quoteSet = shuffleWithAnswer(book.quote, p.quoteWrong, seed + 2);
  qs.push({ q: l.quoteQ, ...quoteSet, why: l.quoteWhy });

  return qs.slice(0, 5);
}
